  // Secret OS History (Phase 5 · M13) — a small original changelog-as-lore,
  // paged through one entry per `history` command in the Aero/Wired terminal.
  'secretHistory.firstLight.title': 'First Light',
  'secretHistory.firstLight.body':
    'Before there was a desktop, there was a leaf, drawn in glass, catching light that had nowhere else to go.',
  'secretHistory.secondDoor.title': 'The Second Door',
  'secretHistory.secondDoor.body':
    'They say the first door was never the only one. The second answers to a quieter word — a word this OS is made of.',
  'secretHistory.warmStatic.title': 'Warm Static',
  'secretHistory.warmStatic.body':
    'Somewhere past the glass, a second signal was already broadcasting. It had been waiting for someone to tune in.',
  'secretHistory.openWater.title': 'Open Water',
  'secretHistory.openWater.body':
    'The coastline finished assembling itself and did not disassemble again. This was the first day it stayed.',
  'secretHistory.companionsArrive.title': 'Companions Arrive',
  'secretHistory.companionsArrive.body':
    'Small shapes began wandering the desktop, unbothered by how new everything still was.',
  'secretHistory.keepsakes.title': 'Keepsakes',
  'secretHistory.keepsakes.body':
    'The companions started bringing things back from wherever they wandered. Nothing important — just small proof they had gone somewhere.',
  'secretHistory.leaf.found': 'You found the second door.',

